import 'dart:convert';
import 'dart:io';

/// Embed first-party browser source as Dart constants, without Flutter assets.
void main(List<String> args) {
  if (args.any((arg) => arg != '--check')) {
    stderr.writeln('Usage: dart run tool/embed_dashboard.dart [--check]');
    exitCode = 64;
    return;
  }
  final output = StringBuffer(
    '// GENERATED by dart run tool/embed_dashboard.dart. Do not edit.\n\n',
  );
  for (final entry in const {
    'dashboardHtml': 'web/dashboard.html',
    'dashboardJs': 'web/dashboard.js',
    'dashboardCss': 'web/dashboard.css',
  }.entries) {
    final content = File(entry.value).readAsStringSync();
    final json = jsonEncode(content);
    final escaped = json
        .substring(1, json.length - 1)
        .replaceAll(r'\"', '"')
        .replaceAll("'", r"\'")
        .replaceAll(r'$', r'\$');
    final literal = "'$escaped'";
    output.writeln('const ${entry.key} =\n    $literal;');
  }
  final destination = File('lib/src/server/assets.dart');
  final generated = output.toString();
  if (args.contains('--check')) {
    if (!destination.existsSync() ||
        destination.readAsStringSync() != generated) {
      stderr.writeln(
        'Dashboard assets are stale. Run dart run tool/embed_dashboard.dart.',
      );
      exitCode = 1;
    }
  } else {
    destination.writeAsStringSync(generated);
  }
}
